(function() {
    var cdnList = [
        'https://lib.baomitu.com/jquery/3.6.0/jquery.min.js',
        'https://cdn.bootcdn.net/ajax/libs/jquery/3.6.0/jquery.min.js',
        'https://cdnjs.cloudflare.com/ajax/libs/jquery/3.6.0/jquery.min.js',
        'https://unpkg.com/jquery@3.6.0/dist/jquery.min.js'
    ];

    var loaded = false;                // 标记是否已有成功加载
    var timeoutId = null;             // 超时定时器句柄

    function tryLoad(src) {
        var script = document.createElement('script');
        script.src = src;
        script.onload = function() {
            // 只在尚未加载成功且 jQuery 真的可用时标记
            if (!loaded && typeof window.jQuery !== 'undefined') {
                loaded = true;
                clearTimeout(timeoutId);
                console.log('jQuery 已加载：' + src);
                // 可触发自定义事件，通知后续业务代码
                // document.dispatchEvent(new Event('jQueryReady'));
            }
        };
        // 单个失败不影响整体，继续等待其他
        script.onerror = function() {
            // 不做特殊处理，因为还有其他 CDN 在尝试
        };
        document.head.appendChild(script);
    }

    // 同时发起所有 CDN 请求（并发）
    cdnList.forEach(tryLoad);

    // 设置超时保护（防止网络慢导致无限等待，默认 5 秒）
    timeoutId = setTimeout(function() {
        if (!loaded && typeof window.jQuery === 'undefined') {
            console.error('所有 CDN 加载超时，请检查网络或使用本地备用');
            // 可在此处尝试加载本地 fallback，例如：
            tryLoad('jquery.min-3.6.0.js');
        }
    }, 5000); // 5 秒后若还未成功则报错
})();